```java
public class Main {

    /**
     * Retrieves the file extension from the provided file name, falling back to a specified default value if no extension is present.
     * 
     * @param fileName the file name to extract the extension from
     * @param defaultValue the default value to return if no extension is found
     * @return the file extension, or the specified default value if no extension is found
     */
    public static String getFileExtension(String fileName, String defaultValue) {
        // Find the last occurrence of a dot in the file name
        int lastDotIndex = fileName.lastIndexOf('.');

        // If no dot is found, return the default value
        if (lastDotIndex == -1) {
            return defaultValue;
        }

        // Extract the file extension
        String extension = fileName.substring(lastDotIndex + 1);

        // Return the file extension
        return extension;
    }

    public static void main(String[] args) {
        // Example usage:
        System.out.println(getFileExtension("example.txt", "unknown"));  // Outputs: txt
        System.out.println(getFileExtension("example", "unknown"));  // Outputs: unknown
    }
}
```

