/**
 * Extracts the file extension from a given file name, returning a specified default value if the file name does not contain an extension.
 *
 * @param fileName the name of the file from which to extract the extension
 * @param default  the default value to return if the file name does not contain an extension
 * @return the extracted file extension as a string, or the specified default value if no extension is found
 * @throws NullPointerException if the default parameter is null
 */
public String extractFileExtension(String fileName, String defaultExtension) {
    // Check if the default parameter is null and throw a NullPointerException if it is
    if (defaultExtension == null) {
        throw new NullPointerException("Default extension cannot be null");
    }

    // Find the last occurrence of a dot in the file name
    int extensionIndex = fileName.lastIndexOf('.');

    // If no dot is found, return the default extension
    if (extensionIndex == -1) {
        return defaultExtension;
    }

    // Extract the file extension by taking the substring starting from the last dot
    String fileExtension = fileName.substring(extensionIndex + 1);

    // Return the extracted file extension
    return fileExtension;
}

