/**
 * Calculates the greatest common divisor (GCD) of two integers using the Euclidean algorithm.
 * 
 * This method takes two integers as input and returns their GCD. It uses the Euclidean algorithm
 * to efficiently calculate the GCD, which is the largest number that divides both input integers
 * without leaving a remainder.
 * 
 * @param a the first integer
 * @param b the second integer
 * @return the greatest common divisor of a and b
 * @throws IllegalArgumentException if either a or b is not a positive integer
 */
public class Main {
    public static int calculateGcd(int a, int b) {
        // Check if both inputs are positive integers
        if (a <= 0 || b <= 0) {
            throw new IllegalArgumentException("Both inputs must be positive integers");
        }

        // Use the Euclidean algorithm to calculate the GCD
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }

        return a;
    }

    public static void main(String[] args) {
        System.out.println(calculateGcd(48, 18));  // Output: 6
    }
}

