/**
 * Reads a value from the specified byte array.
 * 
 * @param {Uint8Array} bytes The input byte array to read from.
 * @param {number} [offset=0] The starting position in the byte array.
 * @param {number} [length=bytes.length] The number of bytes to read.
 * @returns {*} The read value.
 */
function readValue(bytes, offset = 0, length = bytes.length) {
    // Determine the type of the value based on the length
    if (length === 1) {
        // Read a single byte as an unsigned integer
        return bytes[offset];
    } else if (length === 2) {
        // Read two bytes as an unsigned short integer
        return (bytes[offset] << 8) | bytes[offset + 1];
    } else if (length === 4) {
        // Read four bytes as an unsigned integer
        return (bytes[offset] << 24) | (bytes[offset + 1] << 16) | (bytes[offset + 2] << 8) | bytes[offset + 3];
    } else if (length === 8) {
        // Read eight bytes as a big-endian unsigned long long integer
        return (bytes[offset] << 56) | (bytes[offset + 1] << 48) | (bytes[offset + 2] << 40) | (bytes[offset + 3] << 32) | (bytes[offset + 4] << 24) | (bytes[offset + 5] << 16) | (bytes[offset + 6] << 8) | bytes[offset + 7];
    } else {
        // If the length is not supported, throw an error
        throw new Error(`Unsupported length: ${length}`);
    }
}

