import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.Optional;

public class DateRetriever {

    /**
     * Retrieves the ZonedDateTime associated with the given name, parsing the date string in RFC 1123 format.
     * 
     * @param name the name to find the date for
     * @return a non-empty Optional containing the ZonedDateTime if found, or an empty Optional if the date string is invalid
     */
    public static Optional<ZonedDateTime> retrieveDate(String name) {
        // Define the date format in RFC 1123 format
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("EEE, dd MMM yyyy HH:mm:ss z");

        try {
            // Attempt to parse the date string
            ZonedDateTime date = ZonedDateTime.parse(name, formatter);
            // If parsing is successful, return the date wrapped in an Optional
            return Optional.of(date);
        } catch (DateTimeParseException e) {
            // If parsing fails, return an empty Optional
            return Optional.empty();
        }
    }

    public static void main(String[] args) {
        // Example usage:
        String validDate = "Wed, 21 Sep 2022 14:30:00 +0000";
        String invalidDate = "Invalid date string";

        Optional<ZonedDateTime> validResult = retrieveDate(validDate);
        Optional<ZonedDateTime> invalidResult = retrieveDate(invalidDate);

        System.out.println(validResult.isPresent() ? "Found date: " + validResult.get() : "No date found");
        System.out.println(invalidResult.isPresent() ? "Found date: " + invalidResult.get() : "No date found");
    }
}

