    }

    // Compare RAM information
    if (expectedHardware.ram !== actualHardware.ram) {
        report.passed = false;
        report.messages.push(`RAM mismatch: expected ${expectedHardware.ram} but got ${actualHardware.ram}`);
    }

    // Compare storage information
    if (expectedHardware.storage !== actualHardware.storage) {
        report.passed = false;
        report.messages.push(`Storage mismatch: expected ${expectedHardware.storage} but got ${actualHardware.storage}`);
    }

    // Compare graphics information
    if (expectedHardware.graphics !== actualHardware.graphics) {
        report.passed = false;
        report.messages.push(`Graphics mismatch: expected ${expectedHardware.graphics} but got ${actualHardware.graphics}`);
    }

    // Compare other hardware information
    if (expectedHardware.other !== actualHardware.other) {
        report.passed = false;
        report.messages.push(`Other hardware mismatch: expected ${expectedHardware.other} but got ${actualHardware.other}`);
    }

    return report;
}

