/**
 * Validates the given extension model, ensuring correct implementation of equals and hashCode methods.
 * 
 * @param extensionModel The extension model instance to be validated.
 * @param problemsReporter The reporter to use for reporting any issues encountered during validation.
 */
public void validateExtensionModel(ExtensionModel extensionModel, ProblemsReporter problemsReporter) {
    // Check if the extension model implements the equals and hashCode methods
    if (!extensionModel.getClass().getDeclaredMethods().stream()
            .anyMatch(method -> method.getName().equals("equals") && method.getParameterCount() == 1)
            || !extensionModel.getClass().getDeclaredMethods().stream()
                    .anyMatch(method -> method.getName().equals("hashCode") && method.getParameterCount() == 0)) {
        problemsReporter.reportIssue("The extension model must implement the equals and hashCode methods.");
    }

    // Check if the equals method is correctly implemented
    try {
        // Test the equals method with null
        if (extensionModel.equals(null)) {
            problemsReporter.reportIssue("The equals method should return false when comparing with null.");
        }

        // Test the equals method with the same instance
        if (!extensionModel.equals(extensionModel)) {
            problemsReporter.reportIssue("The equals method should return true when comparing with the same instance.");
        }

        // Test the equals method with a different instance
        if (extensionModel.equals(new Object())) {
            problemsReporter.reportIssue("The equals method should return false when comparing with a different instance.");
        }
    } catch (Exception e) {
        problemsReporter.reportIssue("An error occurred while testing the equals method: " + e.getMessage());
    }

    // Check if the hashCode method is correctly implemented
    try {
        // Test the hashCode method with the same instance
        if (extensionModel.hashCode() != extensionModel.hashCode()) {
            problemsReporter.reportIssue("The hashCode method should return the same value when called multiple times.");
        }

        // Test the hashCode method with a different instance
        if (extensionModel.hashCode() == new Object().hashCode()) {
            problemsReporter.reportIssue("The hashCode method should return a different value when comparing with a different instance.");
        }
    } catch (Exception e) {
        problemsReporter.reportIssue("An error occurred while testing the hashCode method: " + e.getMessage());
    }
}

