/**
 * Validates an extension model against expected configuration and connection provider models.
 * 
 * This method iterates over the extension model's configuration and connection provider models,
 * validating parameter types and override checks for equals and hashCode methods on object types.
 * 
 * @param {object} extensionModel The extension model to validate.
 * @param {object} problemsReporter The reporter to report any validation problems encountered.
 */
function validateExtensionModel(extensionModel, problemsReporter) {
  // Iterate over the extension model's configuration and connection provider models
  Object.keys(extensionModel).forEach((key) => {
    const model = extensionModel[key];

    // Validate parameter types
    if (typeof model !== 'object') {
      problemsReporter.reportProblem(`Invalid type for ${key}: expected object, got ${typeof model}`);
    }

    // Validate override checks for equals and hashCode methods on object types
    if (typeof model === 'object' && model !== null) {
      if (!model.equals || typeof model.equals !== 'function') {
        problemsReporter.reportProblem(`Missing or invalid equals method for ${key}`);
      }

      if (!model.hashCode || typeof model.hashCode !== 'function') {
        problemsReporter.reportProblem(`Missing or invalid hashCode method for ${key}`);
      }
    }
  });
}
